from dataclasses import dataclass, field


@dataclass
class Item:
    sku: str
    name: str
    price_cents: int
    qty: int = 0
    tags: list = field(default_factory=list)


class Inventory:
    def __init__(self):
        self.items = {}

    def add(self, item):
        if item.sku in self.items:
            self.items[item.sku].qty += item.qty
        else:
            self.items[item.sku] = item

    def remove(self, sku, qty):
        it = self.items[sku]
        it.qty -= qty
        if it.qty < 0:
            it.qty = 0

    def total_value(self):
        total = 0
        for it in self.items.values():
            total += it.price_cents * it.qty
        return total

    def apply_discount(self, tag, percent):
        for it in self.items.values():
            if tag in it.tags:
                it.price_cents = it.price_cents * percent // 100

    def find_by_tag(self, tag):
        return [it for it in self.items.values() if tag in it.tags]
```
