File ring.c:
```c
#include <stddef.h>
#include <stdint.h>
#include <string.h>

typedef struct {
    uint8_t *buf;
    size_t cap;   /* power of two */
    size_t head;  /* next write */
    size_t tail;  /* next read */
} ring_t;

int ring_init(ring_t *r, uint8_t *storage, size_t cap) {
    if (cap == 0 || (cap & (cap - 1)) != 0) return -1;
    r->buf = storage;
    r->cap = cap;
    r->head = r->tail = 0;
    return 0;
}

size_t ring_used(const ring_t *r) { return r->head - r->tail; }

size_t ring_write(ring_t *r, const uint8_t *src, size_t n) {
    size_t space = r->cap - ring_used(r);
    if (n > space) n = space;
    for (size_t i = 0; i < n; i++)
        r->buf[(r->head + i) & r->cap] = src[i];
    r->head += n;
    return n;
}

size_t ring_read(ring_t *r, uint8_t *dst, size_t n) {
    size_t used = ring_used(r);
    if (n > used) n = used;
    for (size_t i = 0; i < n; i++)
        dst[i] = r->buf[(r->tail + i) & (r->cap - 1)];
    r->tail += n;
    return n;
}
```
There is an indexing bug in ring_write. Fix it, and add `size_t ring_peek(const ring_t *r, uint8_t *dst, size_t n)` that copies like ring_read without consuming. Answer as a unified diff (`--- a/ring.c` / `+++ b/ring.c`) and nothing else.

